package com.collegeerp.erp.academic.entity;
import com.collegeerp.erp.academic.enums.AcademicStatus; import com.collegeerp.erp.common.entity.BaseAuditEntity; import com.collegeerp.erp.staff.entity.StaffProfile; import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="subject_teacher_assignments") public class SubjectTeacherAssignment extends BaseAuditEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subject_id",nullable=false) private Subject subject; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="teacher_id",nullable=false) private StaffProfile teacher; @ManyToMany @JoinTable(name="subject_teacher_divisions",joinColumns=@JoinColumn(name="assignment_id"),inverseJoinColumns=@JoinColumn(name="section_id")) private Set<Section> sections=new LinkedHashSet<>(); @Column(name="academic_year",nullable=false) private String academicYear; @Enumerated(EnumType.STRING) private AcademicStatus status=AcademicStatus.ACTIVE; private LocalDateTime assignedAt=LocalDateTime.now(); public Long getId(){return id;} public Subject getSubject(){return subject;} public void setSubject(Subject v){subject=v;} public StaffProfile getTeacher(){return teacher;} public void setTeacher(StaffProfile v){teacher=v;} public Set<Section> getSections(){return sections;} public void setSections(Collection<Section> v){sections=v==null?new LinkedHashSet<>():new LinkedHashSet<>(v);} public String getAcademicYear(){return academicYear;} public void setAcademicYear(String v){academicYear=v;} public AcademicStatus getStatus(){return status;} public void setStatus(AcademicStatus v){status=v;} public LocalDateTime getAssignedAt(){return assignedAt;} }
